-- ===== 20261022000006_storage.sql =====

-- =============================================================================
-- Storage: one public bucket for catalog and brand images.
--   products/<product_id>/<file>   -> products permission
--   categories/<category_id>/<file> -> products permission
--   store/<file>                    -> settings permission
-- Size and MIME type are enforced by the bucket and again by the server action.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('catalog', 'catalog', true, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/avif'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create policy catalog_staff_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'catalog' and (
      ((storage.foldername(name))[1] in ('products', 'categories') and public.has_permission('products'))
      or ((storage.foldername(name))[1] = 'store' and public.has_permission('settings'))
    )
  );

create policy catalog_staff_update on storage.objects for update to authenticated
  using (
    bucket_id = 'catalog' and (
      ((storage.foldername(name))[1] in ('products', 'categories') and public.has_permission('products'))
      or ((storage.foldername(name))[1] = 'store' and public.has_permission('settings'))
    )
  );

create policy catalog_staff_delete on storage.objects for delete to authenticated
  using (
    bucket_id = 'catalog' and (
      ((storage.foldername(name))[1] in ('products', 'categories') and public.has_permission('products'))
      or ((storage.foldername(name))[1] = 'store' and public.has_permission('settings'))
    )
  );

-- Staff can list files they manage; the public reads files by URL only.
create policy catalog_staff_select on storage.objects for select to authenticated
  using (bucket_id = 'catalog' and public.is_staff());


-- ===== 20261026000007_catalog_option_filters.sql =====

-- Option filters for the storefront catalog: shoppers can narrow a category by
-- variant options such as Size, Color or Fits (the phone model a case is made for).
-- catalog_search gains p_options, e.g. {"Size": ["M", "L"], "Fits": ["iPhone 15"]}:
-- a product matches when, for every option named, one of its active variants
-- carries one of the listed values. catalog_option_facets lists the values on
-- offer in a category so the filter panel only shows choices that exist.

drop function if exists public.catalog_search(text, text, numeric, numeric, text, boolean, boolean, integer, integer);

create or replace function public.catalog_search(
  p_query text default null,
  p_category_slug text default null,
  p_min_price numeric default null,
  p_max_price numeric default null,
  p_sort text default 'newest',
  p_in_stock boolean default false,
  p_featured boolean default false,
  p_limit integer default 24,
  p_offset integer default 0,
  p_options jsonb default null
)
returns table (
  id uuid, name text, slug text, short_description text,
  price numeric, sale_price numeric, effective_price numeric,
  min_variant_price numeric, max_variant_price numeric,
  rating_avg numeric, rating_count integer, sold_count integer,
  published_at timestamptz, category_name text, category_slug text,
  image_url text, image_alt text, total_stock bigint, low_stock_threshold integer,
  variant_count bigint, default_variant_id uuid, total_count bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  with recursive
  terms as (
    select string_agg(w || ':*', ' & ') as tsq
    from regexp_split_to_table(
      lower(regexp_replace(left(coalesce(p_query, ''), 100), '[^[:alnum:][:space:]]', ' ', 'g')), '\s+'
    ) w
    where w <> ''
  ),
  cat_tree as (
    select c.id from public.categories c where p_category_slug is not null and c.slug = p_category_slug
    union all
    select c.id from public.categories c join cat_tree t on c.parent_id = t.id
  ),
  base as (
    select p.*, c.name as category_name, c.slug as category_slug,
           case when t.tsq is null then 0 else ts_rank(p.search_vector, to_tsquery('simple', t.tsq)) end as rank,
           v.min_price, v.max_price, v.total_stock, v.variant_count, v.default_variant_id
    from public.products p
    cross join terms t
    left join public.categories c on c.id = p.category_id
    cross join lateral (
      select min(public.compute_unit_price(p.price, p.sale_price, pv.price, pv.sale_price)) as min_price,
             max(public.compute_unit_price(p.price, p.sale_price, pv.price, pv.sale_price)) as max_price,
             coalesce(sum(pv.stock_quantity), 0) as total_stock,
             count(*) as variant_count,
             (array_agg(pv.id order by (pv.stock_quantity > 0) desc, pv.position, pv.created_at))[1] as default_variant_id
      from public.product_variants pv
      where pv.product_id = p.id and pv.is_active
    ) v
    where p.status = 'active'
      and v.variant_count > 0
      and (t.tsq is null or p.search_vector @@ to_tsquery('simple', t.tsq))
      and (p_category_slug is null or p.category_id in (select cat_tree.id from cat_tree))
      and (p_min_price is null or v.min_price >= p_min_price)
      and (p_max_price is null or v.min_price <= p_max_price)
      and (not p_in_stock or v.total_stock > 0)
      and (not p_featured or p.is_featured)
      and (p_options is null or jsonb_typeof(p_options) <> 'object' or not exists (
        select 1 from jsonb_each(p_options) o(name, vals)
        where jsonb_typeof(o.vals) = 'array' and jsonb_array_length(o.vals) > 0
          and not exists (
            select 1 from public.product_variants pv
            where pv.product_id = p.id and pv.is_active
              and pv.options ->> o.name in (select jsonb_array_elements_text(o.vals))
          )
      ))
  )
  select b.id, b.name, b.slug, b.short_description,
         b.price, b.sale_price, b.effective_price,
         b.min_price, b.max_price,
         b.rating_avg, b.rating_count, b.sold_count,
         b.published_at, b.category_name, b.category_slug,
         img.url, img.alt, b.total_stock, b.low_stock_threshold,
         b.variant_count, b.default_variant_id,
         count(*) over () as total_count
  from base b
  left join lateral (
    select i.url, i.alt from public.product_images i
    where i.product_id = b.id order by i.position, i.created_at limit 1
  ) img on true
  order by
    case when p_sort = 'price_asc' then b.min_price end asc nulls last,
    case when p_sort = 'price_desc' then b.min_price end desc nulls last,
    case when p_sort = 'popular' then b.sold_count end desc nulls last,
    case when p_sort = 'rating' then b.rating_avg end desc nulls last,
    case when p_sort = 'relevance' then b.rank end desc nulls last,
    b.published_at desc nulls last,
    b.id
  limit least(greatest(p_limit, 1), 60)
  offset greatest(p_offset, 0);
$$;

grant execute on function public.catalog_search(text, text, numeric, numeric, text, boolean, boolean, integer, integer, jsonb)
  to anon, authenticated;

create or replace function public.catalog_option_facets(p_category_slug text default null)
returns table (name text, value text, product_count bigint)
language sql
stable
security invoker
set search_path = ''
as $$
  with recursive cat_tree as (
    select c.id from public.categories c where p_category_slug is not null and c.slug = p_category_slug
    union all
    select c.id from public.categories c join cat_tree t on c.parent_id = t.id
  )
  select o.key, o.value, count(distinct p.id)
  from public.products p
  join public.product_variants pv on pv.product_id = p.id and pv.is_active
  cross join lateral jsonb_each_text(pv.options) o
  where p.status = 'active'
    and (p_category_slug is null or p.category_id in (select cat_tree.id from cat_tree))
  group by o.key, o.value
  order by o.key, min(pv.position), o.value;
$$;

grant execute on function public.catalog_option_facets(text) to anon, authenticated;


-- ===== 20261026000008_review_photos.sql =====

-- Review photos: verified buyers can attach up to 4 photos to their review.
--   Files live in the public catalog bucket under reviews/<user_id>/<file>, and
--   storage RLS lets each customer write only inside their own folder.
--   reviews.photos keeps the storage paths; the app turns them into public URLs.
--   submit_review gains p_photos (null keeps a review's existing photos, an
--   empty array removes them) and checks every path belongs to the caller.

alter table public.reviews
  add column if not exists photos text[] not null default '{}'
  check (cardinality(photos) <= 4);

drop function if exists public.submit_review(uuid, integer, text, text);

create or replace function public.submit_review(
  p_product_id uuid, p_rating integer, p_title text, p_body text, p_photos text[] default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_order uuid;
  v_id uuid;
  v_name text;
  v_path text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  perform public.enforce_rate_limit('review:' || v_uid::text, 10, 3600);

  select o.id into v_order from public.orders o join public.order_items i on i.order_id = o.id
    where o.user_id = v_uid and o.status = 'delivered' and i.product_id = p_product_id
    order by o.placed_at desc limit 1;
  if v_order is null then
    raise exception 'REVIEW_NOT_ELIGIBLE' using errcode = '42501';
  end if;
  if p_rating not between 1 and 5 then
    raise exception 'INVALID_RATING' using errcode = '22023';
  end if;
  if p_photos is not null then
    if cardinality(p_photos) > 4 then
      raise exception 'TOO_MANY_PHOTOS' using errcode = '22023';
    end if;
    foreach v_path in array p_photos loop
      if v_path is null or v_path !~ ('^reviews/' || v_uid::text || '/[0-9a-f-]{36}\.(jpg|png|webp|avif)$') then
        raise exception 'INVALID_PHOTO' using errcode = '22023';
      end if;
    end loop;
  end if;

  select coalesce(nullif(split_part(trim(full_name), ' ', 1), ''), 'Verified buyer') into v_name
    from public.profiles where id = v_uid;

  insert into public.reviews (product_id, user_id, order_id, author_name, rating, title, body, photos)
  values (p_product_id, v_uid, v_order, coalesce(v_name, 'Verified buyer'), p_rating,
          nullif(left(trim(p_title), 120), ''), nullif(left(trim(p_body), 3000), ''), coalesce(p_photos, '{}'))
  on conflict (product_id, user_id) do update
    set rating = excluded.rating, title = excluded.title, body = excluded.body,
        photos = case when p_photos is null then public.reviews.photos else excluded.photos end
  returning id into v_id;
  return v_id;
end;
$$;

grant execute on function public.submit_review(uuid, integer, text, text, text[]) to authenticated;

-- Customers upload and remove photos in their own reviews/<user_id>/ folder only.
create policy catalog_review_photo_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'catalog'
    and (storage.foldername(name))[1] = 'reviews'
    and (storage.foldername(name))[2] = auth.uid()::text
  );

create policy catalog_review_photo_delete on storage.objects for delete to authenticated
  using (
    bucket_id = 'catalog'
    and (storage.foldername(name))[1] = 'reviews'
    and (storage.foldername(name))[2] = auth.uid()::text
  );

-- Removing a file also needs read access to it.
create policy catalog_review_photo_select on storage.objects for select to authenticated
  using (
    bucket_id = 'catalog'
    and (storage.foldername(name))[1] = 'reviews'
    and (storage.foldername(name))[2] = auth.uid()::text
  );


commit;
